<?php

namespace Database\Seeders\Support;

/**
 * Japanese word => its meaning in every native language a Japanese course
 * supports (English, Spanish, German, French, Korean).
 *
 * Japanese is the LEARNING language here, so exercise content (words, phrases,
 * tiles) is authored in Japanese, and only the hints/prompts are shown in the
 * learner's own language. Nothing user-facing is hardcoded: seeders pull from
 * here and store the result as an ['i18n' => [...]] map, which
 * ExerciseContentService resolves per request.
